custom_css:
/*
 * 酒馆主题：泊秦淮·烟笼寒水（日）
 * 作者：吃一口月亮（赋月）
 * 发布于dc社区（账号同名），禁擅自二传/商用，可二改自用
 * 字素xhs无敌枝笺老师，加载界面字素来自于月本人，弹窗背景图xhs@5749970348
 * 基于@墨千尾老师的基础框架修改而成
 * 感谢@毛毛雨老师的很多优化思路指导
 * 感谢lc美化区教程楼各位老师，使用的代码有标注
 */

/* 先导篇：字体导入 */
@import url("https://fontsapi.zeoseven.com/256/main/result.css");


/* ===一、全局控制=== */
:root {
  /* === 字体 === */
  --主字体: "Huiwen-mincho", serif;

  /* === 自定义文案 === */
  --自定义思维链文案: "『招取楼边月，同载扁舟』";
  --自定义加载更多信息文案:" 〖 月落乌啼霜满天 〗 ";
  --自定义输入框文字: "『 隔江犹唱后庭花 』";

  /* === 🎨 核心色彩 === */
  --主文字色: rgba(15, 15, 15, 1);
  --引用文字色: #5a2222;
  --引用背景色: #f4f1ea;
  --斜体背景色: rgba(100, 110, 130, 0.15);

  /* === 🖋️ 描边系统  === */
  --烛光投影:
  drop-shadow(0 1px 1px rgba(30, 35, 45, 0.12));
  --暗黑底色: rgba(255, 255, 255, 0.92);
  --次暗底色: rgba(255, 255, 255, 0.88);

  /* === ✨ 阴影体系 === */
  --阴影黑色不大: 0 1px 3px rgba(30, 35, 45, 0.2), 0 1px 2px rgba(30, 35, 45, 0.12);
  --阴影多层奢华:
  0 0 0 1px rgba(30, 35, 45, 0.12),
  0 0 0 2px rgba(180, 185, 195, 0.4),
  0 0 0 3px rgba(30, 35, 45, 0.08),
  2px 3px 6px rgba(30, 35, 45, 0.18);
  --阴影内凹深:
  inset 2px 2px 4px rgba(0,0,0,0.3),
  inset -1px -1px 2px rgba(255,255,255,0.8);
  --阴影面板:
  0 0 0 1px rgba(30, 35, 45, 0.08),
  0 2px 8px rgba(30, 35, 45, 0.15);
  --按钮按下: translateY(2px) scale(0.97);

  /* === 🖋️ 描边系统  === */
  --墨描边色: rgba(30, 35, 45, 0.2);
  --墨描边宽: 0.8px;

  /* === 🌊 江面渐变（底栏专用） === */
  --江面渐变:
    linear-gradient(
      to bottom,
      transparent 0%,
      rgba(215, 222, 218, 0.45) 35%,
      rgba(228, 234, 230, 0.8) 75%,
      rgba(240, 242, 238, 0.95) 100%
    );

  /* === 🎋 高度锁 === */
  --底栏最小高: 48px;
  --底栏最大高: 300px;
  --弹窗高度:12px;
  --顶栏背景图宽度: 100%;
  --顶栏背景图高度: 300px;
  --顶栏背景图上下: -10px;
  --顶栏背景图左右: 0px;

  /* === 📐 气泡尺寸 === */
  --气泡最大宽度: 500px;
  --气泡上间距: 300px;
  --气泡下间距: 180px;
  --气泡顶部图高度: 400px;
  --气泡底部图高度: 300px;

  /* === 🖼️ 头像位置 === */
  --头像上下: -78px;
  --头像左右: 50%;
  --头像宽度: 300px;
  --头像高度: 260px;
  --头像遮罩位置: center 30%;

  /* === 📝 名字位置（纵排竖字） === */
  --名字上下: -40px;
  --名字左右: 55px;
  --名字字体大小: 10px;

  /* === 🕐 时间戳与三元素 === */
  --时间戳上下: 102px;
  --时间戳左右: 61%;
  --时间戳字体大小: 9px;

  --楼层上下: 45px;
  --楼层左右: 20%;
  --计时器上下: 58px;
  --计时器左右: 15%;
  --计数器上下: 82px;
  --计数器左右: 19%;
  --三元素字体大小: 9px;

  /* === ✏️ 气泡按钮位置（小铅笔&省略号）=== */
  --按钮组上下: 110px;
  --按钮组左右: 68%;
  --按钮间距: 0px;

  --展开菜单上下: 200px;
  --展开菜单右: 75%;

  /* === ✏️ 编辑框位置变量 === */
  --编辑框上下: 50px;
  --编辑框左右: 0%;

  /* === ✏️ 编辑确认/取消按钮位置变量 === */
  --编辑按钮上下: -40px;
  --编辑按钮左右: 50%;

  /* === 💭 思维链 === */
  --思维链标题上下: 135px;
  --思维链标题左右: 45%;
  --思维链文字大小: 12px;
  --思维链最大高度: 220px;

  /* === 📄 文本内边距 === */
  --文本区域上边距: 200px;
  --文本区域左边距: 7%;
  --文本区域右边距: 7%;
  --文本区域下边距: 150px;
  --正文上边距: 0px;
  --正文右边距: 0px;
  --正文下边距: 0px;
  --正文左边距: 0px;

  /* === ◀️▶️ 翻页 === */
  --左箭头上下: -60px;
  --左箭头左右: 5px;
  --右箭头上下: -75px;
  --右箭头左右: 63px;

  /* === ◎ 页码位置 === */
  --页码上下: -33px;
  --页码左右: 85px;
  --页码大小: 10px;

  /* === 🎋 底栏 === */
  --底栏图标大小: 18px;
  --底栏图标间隔: 5px;

  /* === 顶栏图标位置（逐个上下微调） === */
  --图标1上下: 5px;
  --图标2上下: 25px;
  --图标3上下: 10px;
  --图标4上下: 30px;
  --图标5上下: 15px;
  --图标6上下: 25px;
  --图标7上下: 15px;
  --图标8上下: 10px;
  --图标9上下: 25px;
  --图标10上下: 20px;
  --图标11上下: 5px;

  /* === 👻 小幽灵 === */
  --小幽灵宽度: 500px;
  --小幽灵高度: 300px;
  --小幽灵上下: -240px;
  --小幽灵左右: -30px;
  --小幽灵左渐隐: 350px;
}


/* 定义全局字体 */
body {
  font-family: var(--主字体);
  font-weight: normal;
  font-style: normal;
  color: var(--主文字色);
}

/* 全局圆角清零 */
*,
*::before,
*::after {
  border-radius: 0 !important;
}

/* 去除文字原生阴影（统一由墨描边接管） */
* {
  text-shadow: none !important;
}

/* 隐藏启动页的 Logo 图片@风雪夜归人 */
.splash-logo {
  display: none !important;
}

/* 全局隐藏滚动条@咩野 */
#chat::-webkit-scrollbar {
  display: none;
}
::-webkit-scrollbar {
  width: 0px;
  height: 0px;
  display: none;
}
* {
  scrollbar-width: none;
  -ms-overflow-style: none;
}

/* 定义全局弹出面板主色调 */
.drawer-content {
  background-color: var(--暗黑底色) !important;
  border: 1px solid rgba(90, 100, 105, 0.15) !important;
  box-shadow: var(--阴影面板) !important;
}

#table_drawer_content {
  background-color: var(--暗黑底色) !important;
  border: 1px solid rgba(90, 100, 105, 0.15) !important;
}

.options-content {
  background-color: var(--暗黑底色) !important;
  border: 1px solid rgba(90, 100, 105, 0.15) !important;
}


/* ===== 二、顶栏@毛毛雨 ===== */

/* 顶部下拉弹窗@Nakari */
.drawer-content {
  background-image: linear-gradient(rgba(255, 255, 255, 0.6), rgba(255, 255, 255, 0.6)),url('https://iili.io/CYK6uEl.jpg') !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-color: transparent !important;
  border: none !important;
  border-radius: 0px !important;
  top: var(--弹窗高度) !important;
  color: var(--主文字色);
  z-index: 9999 !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
}

/* 去顶栏阴影 */
#top-bar {
  box-shadow: none !important;
}

/* 顶栏透明 */
body.no-blur #top-bar {
  background-color: transparent !important;
}

#top-settings-holder,
#top-settings-holder .drawer,
#top-settings-holder .drawer-toggle,
#top-settings-holder .drawer-header,
#top-bar {
  background-color: transparent !important;
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 允许溢出 */
#top-settings-holder {
  position: relative;
  overflow: visible !important;
}

/* 顶栏背景 */
#top-settings-holder::before {
  content: "";
  position: absolute;
  width: var(--顶栏背景图宽度);
  height: var(--顶栏背景图高度);
  background-image: url("https://iili.io/CYqv2Ra.png");
  background-size: 100% auto;
  background-repeat: no-repeat;
  background-position: center top;
  top: var(--顶栏背景图上下);
  left: var(--顶栏背景图左右);
  pointer-events: none;
  z-index: -2 !important;
}

/* 图标居中 */
#top-settings-holder > div {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

#top-settings-holder .drawer-icon {
  opacity: 0;
  transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1),
              opacity 0.3s ease,
              filter 0.3s ease;
}

#top-settings-holder .drawer-icon::before {
  font-size: 16px;
  color: var(--主文字色);
  filter: var(--烛光投影);
  transition: transform 0.4s ease;
}

/* 悬停：上浮+烛光加亮 */
#top-settings-holder .drawer-icon:hover {
  opacity: 1;
  transform: translateY(-2px) rotate(-6deg);
  filter: drop-shadow(0 0 4px rgba(140, 150, 165, 0.45))
          drop-shadow(1px 1px 1.5px rgba(70, 75, 85, 0.35));
}

#top-settings-holder .drawer-icon.openIcon {
  opacity: 1;
  transform: rotate(0deg);
}

#top-settings-holder .drawer-icon:active {
  transform: var(--按钮按下) !important;
}

/* 顶栏图标替换区 */
/* 顶栏图标组整体@墨千尾 */

/* 隐藏原fa图标文字 */
#top-settings-holder .drawer-icon::before {
  content: '' !important;
  font-size: 0 !important;
}

/* 图标容器统一基础 */
#top-settings-holder .drawer-icon {
  width: 32px !important;
  height:32px !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1),
              opacity 0.3s ease,
              filter 0.3s ease;
}

/* 默认隐藏（改成0.8就是半透明常驻显示） */
.drawer-icon:not(.openIcon) {
  opacity: 0 !important;
}

/* 悬停单个图标：上浮+旋转 */
#top-settings-holder .drawer-icon:hover {
  opacity: 1 !important;
  transform: translateY(-2px) rotate(-6deg);
  filter: drop-shadow(0 1px 2px rgba(30, 35, 45, 0.25));
}

/* 已展开面板的图标保持显示 */
#top-settings-holder .drawer-icon.openIcon {
  opacity: 1;
  transform: rotate(0deg);
}

/* 按下效果 */
#top-settings-holder .drawer-icon:active {
  transform: var(--按钮按下) !important;
}

/* ✏️ 逐个分配图片 + 变量控制上下位置 */
#top-settings-holder > .drawer:nth-of-type(1) .drawer-icon { background-image: url('https://iili.io/CaRTKFV.png') !important; margin-top: var(--图标1上下) !important; }
#top-settings-holder > .drawer:nth-of-type(2) .drawer-icon { background-image: url('https://iili.io/CaRTq8P.png') !important; margin-top: var(--图标2上下) !important; }
#top-settings-holder > .drawer:nth-of-type(3) .drawer-icon { background-image: url('https://iili.io/CaRTC91.png') !important; margin-top: var(--图标3上下) !important; }
#top-settings-holder > .drawer:nth-of-type(4) .drawer-icon { background-image: url('https://iili.io/CaRTfcB.png') !important; margin-top: var(--图标4上下) !important; }
#top-settings-holder > .drawer:nth-of-type(5) .drawer-icon { background-image: url('https://iili.io/CaRTnAF.png') !important; margin-top: var(--图标5上下) !important; }
#top-settings-holder > .drawer:nth-of-type(6) .drawer-icon { background-image: url('https://iili.io/CaRTxta.png') !important; margin-top: var(--图标6上下) !important; }
#top-settings-holder > .drawer:nth-of-type(7) .drawer-icon { background-image: url('https://iili.io/CaRTcAX.png') !important; margin-top: var(--图标7上下) !important; }
#top-settings-holder > .drawer:nth-of-type(8) .drawer-icon { background-image: url('https://iili.io/CaRTTMv.png') !important; margin-top: var(--图标8上下) !important; }
#top-settings-holder > .drawer:nth-of-type(9) .drawer-icon { background-image: url('https://iili.io/CaRT5cN.png') !important; margin-top: var(--图标9上下) !important; }
#top-settings-holder > .drawer:nth-of-type(10) .drawer-icon { background-image: url('https://iili.io/CaRT7SI.png') !important; margin-top: var(--图标10上下) !important; }
#top-settings-holder > .drawer:nth-of-type(11) .drawer-icon { background-image: url('https://iili.io/CaRTa9t.png') !important; margin-top: var(--图标11上下) !important; }

/* 顶栏图标错峰呼吸动效 */
#top-settings-holder .drawer:nth-child(odd) .drawer-icon::before {
  animation: gentleFloat 5s ease-in-out infinite;
}
#top-settings-holder .drawer:nth-child(even) .drawer-icon::before {
  animation: gentleFloat 5s ease-in-out infinite 2.5s;
}


/* ===== 三、底栏@Nakari ===== */

/* 防止输入框遮挡@秋依@Nakari  */
#sheld {
  top: var(--bottomFormBlockSize);
  height: calc(100dvh - var(--bottomFormBlockSize));
  max-height: calc(100dvh - var(--bottomFormBlockSize));
  min-height: calc(100dvh - var(--bottomFormBlockSize));
}

/* 底栏外层：江面渐变背景 */
#form_sheld {
  position: absolute !important;
  bottom: 0 !important;
  left: 0 !important;
  right: 0 !important;
  background: none !important;
  padding: 14px 0 6px 0 !important;
  pointer-events: auto !important;
  z-index: 100 !important;
}

#nonQRFormItems {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  position: relative !important;
  overflow: visible !important;
}

/* 聊天区底部晕开 */
#chat {
  -webkit-mask-image: linear-gradient(
    to bottom,
    transparent 0%,
    black 100px,
    black 87%,
    transparent 100%
  ) !important;
  mask-image: linear-gradient(
    to bottom,
    transparent 0%,
    black 100px,
    black 87%,
    transparent 100%
  ) !important;
}

/* 底栏本体透明（让渐变透出来） */
#send_form {
  background: none !important;
  border: none !important;
}

#send_form {
  display: flex !important;
  flex-direction: column !important;
  width: 100% !important;
  max-width: 650px !important;
  margin: 0 auto !important;
  padding: 8px 10px !important;
  position: relative !important;
  background: none !important;
  border: 2px double #fff !important;
  box-shadow: var(--阴影黑色不大) !important;
  overflow: visible !important;
  min-height: var(--底栏最小高) !important;
  max-height: var(--底栏最大高) !important;
  overflow-y: auto !important;
  isolation: isolate;
  margin:0 auto 5px auto !important;
  width: calc(100% - 5px * 2) !important;
}

/* ✏️ 底栏背景装饰图 */
#send_form::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: url('https://iili.io/CaYJd0u.png') bottom center / cover no-repeat !important;
  pointer-events: none;
  z-index: -1;
}

/* 悬停效果 */
#send_form:hover {
  box-shadow: var(--阴影多层奢华) !important;
}

/* 去除输入时边框@Nakari */
#send_form:has(#send_textarea:focus-visible) {
  outline: none;
}

/* 输入框透明化@Deleted_User */
#send_textarea {
  clip-path: none !important;
  background-color: transparent !important;
  border-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: var(--主文字色) !important;
  padding: 5px 10px !important;
  line-height: 1.6 !important;
  resize: none !important;
  max-height: 120px !important;
}

/* 强制输入框发送后恢复单行高度@nini */
#send_textarea:placeholder-shown {
  height: 32px !important;
}

/* 去除小黑点@nini */
#send_textarea {
  resize: none;
}

/*  输入框提示文字@墨千尾 */
#nonQRFormItems {
  position: relative;
}

#send_textarea::placeholder {
  color: transparent !important;
  text-shadow: none !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: var(--自定义输入框文字);
  color: rgba(38, 42, 48, 0.6);
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  font-size: 0.35em;
  font-style: normal;
  letter-spacing: 0.2em;
  pointer-events: none;
  z-index: 10;
  white-space: nowrap;
  overflow: hidden;
  max-width: calc(100% - 30px);
  -webkit-text-stroke: 1px var(--墨描边色);
  paint-order: stroke fill;
  filter: var(--烛光投影);
}

/* 聚焦时隐藏@serein */
#nonQRFormItems:has(#send_textarea:focus)::before {
  display: none;
}

/* 底栏图标·烛光浮动 */
#send_form [class*="fa-"]::before {
  font-size: var(--底栏图标大小);
  color: var(--主文字色);
  filter: var(--烛光投影);
  transition: transform 0.3s ease, filter 0.3s ease;
  animation: gentleFloat 4s ease-in-out infinite;
}

#send_form [class*="fa-"]:hover::before {
  transform: translateY(-2px);
  filter: drop-shadow(0 0 4px rgba(140, 150, 165, 0.45))
          drop-shadow(1px 1px 1.5px rgba(70, 75, 85, 0.35));
}

#leftSendForm,
#rightSendForm {
  align-items: center !important;
  gap: var(--底栏图标间隔) !important;
}

/* ===== 底栏图标替换区 ===== */

#options_button::before { display: none !important; }
#options_button {
  background: url('https://iili.io/CaRTKFV.png') no-repeat center / 30px 30px !important;
  width: 30px !important; height: 30px !important;
}
#extensionsMenuButton::before { display: none !important; }
#extensionsMenuButton {
  background: url('https://iili.io/CaRTq8P.png') no-repeat center / 30px 30px !important;
  width: 30px !important; height: 30px !important;
}
#send_but::before { display: none !important; }
#send_but {
  background: url('https://iili.io/CaRTTMv.png') no-repeat center / 30px 30px !important;
  width: 30px !important; height: 30px !important;
}
.fa-circle-stop::before, .fa-stop-circle::before { display: none !important; }
.fa-circle-stop, .fa-stop-circle {
  background: url('https://iili.io/CaRTa9t.png') no-repeat center / 30px 30px !important;
  width: 30px !important; height: 30px !important;
}
#quick-reply-rocket-button i { display: none !important; }
#quick-reply-rocket-button {
  background: url('https://iili.io/CaRT5cN.png') no-repeat center / 30px 30px !important;
  width: 30px !important; height: 30px !important; font-size: 0 !important;
}


/* 隐藏QR@十二 */
.qr--buttons {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  transform: translateY(12px);
  pointer-events: none;
  transition: opacity 0.4s ease, visibility 0.4s ease, max-height 0.5s ease, transform 0.5s ease;
}

#send_form:focus-within .qr--buttons {
  opacity: 1;
  visibility: visible;
  max-height: 90px;
  transform: translateY(0);
  pointer-events: auto;
}

/* user热切换*/
#quickPersonaImg,
.quickPersonaMenuImg {
  opacity: 1 !important;
  border-radius: 0px !important;
  border: 1px solid rgba(90, 100, 105, 0.5) !important;
  outline: 1px solid rgba(255, 255, 255, 0.4) !important;
  outline-offset: -2px;
  box-shadow:
    0 0 5px rgba(200, 220, 225, 0.2),
    2px 3px 5px rgba(90, 100, 105, 0.3) !important;
  transform: translateY(2px);
  transition: transform 0.35s ease, box-shadow 0.35s ease;
}

#quickPersonaImg:hover {
  transform: translateY(-1px);
  box-shadow:
    0 0 7px rgba(200, 220, 225, 0.35),
    3px 4px 8px rgba(90, 100, 105, 0.4) !important;
}

#quickPersonaCaret {
  display: none !important;
}

#quickPersonaMenu {
  background: var(--暗黑底色) !important;
  border: 1px solid rgba(90, 100, 105, 0.2) !important;
  box-shadow: var(--阴影面板) !important;
  padding: 6px !important;
}

#quickPersonaMenu * {
  background-color: transparent !important;
}

#quickPersonaMenu .quickPersonaMenuImg,
#quickPersonaMenu img {
  border-radius: 0 !important;
  border: 1px solid rgba(90, 100, 105, 0.4) !important;
  outline: 1px solid rgba(255, 255, 255, 0.3) !important;
  outline-offset: -2px;
  margin: 3px !important;
  transition: all 0.3s ease;
}

#quickPersonaMenu .quickPersonaMenuImg:hover,
#quickPersonaMenu img:hover {
  outline-color: rgba(90, 100, 105, 0.6) !important;
  transform: scale(1.05);
}


/* ===== 四、聊天区域@Nakari@毛毛雨@墨千尾 ===== */

#chat {
  background-color: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  padding-bottom: 130px !important;
  border:none !important;
}

body.no-blur #chat,
body.no-blur .mes {
  background-color: transparent !important;
}
body.bubblechat .mes {
  background-color: transparent !important;
}


/* ---三段拼接气泡--- */

.mes {
  position: relative !important;
  overflow: visible !important;
  flex-direction: column !important;
  align-items: center !important;
  border: none !important;
  box-shadow: none !important;
  background-color: transparent !important;

  /* ✏️ 中段平铺背景图（填入链接即可生效） */
  background: url('https://iili.io/CYdFWvf.jpg') repeat-y !important;
  background-size: 100% auto !important;
  background-position: top center !important;
  transform-origin: top center !important;

  width: 100% !important;
  max-width: var(--气泡最大宽度) !important;
  margin: var(--气泡上间距) auto var(--气泡下间距) auto !important;
  z-index: 0 !important;
}

/* ✏️ 顶部装饰图 */
.mes::before {
  content: "" !important;
  position: absolute !important;
  top: -220px !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  height: var(--气泡顶部图高度) !important;
  background-image: url('https://iili.io/CYdMxOG.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: bottom center !important;
  pointer-events: none !important;
  z-index: 0 !important;
}

/* ✏️ 底部装饰图 */
.mes::after {
  content: "" !important;
  position: absolute !important;
  bottom: -120px !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  height: var(--气泡底部图高度) !important;
  background-image: url('https://iili.io/CaaDIwP.png') !important;
  /* ✏️ 替换气泡底部图：background-image: url('✏️ 底部装饰图链接') !important; */
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: bottom center !important;
  pointer-events: none !important;
  z-index: -1 !important;
}

.last_mes {
  margin-bottom: 60px !important;
}

/* --- 消息块 --- */
.mes_block {
  overflow: visible !important;
  width: 100% !important;
  margin: 0 !important;
  padding: var(--文本区域上边距) var(--文本区域右边距) var(--文本区域下边距) var(--文本区域左边距) !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  position: relative !important;
}

/* 正文内边距 */
.mes_text {
  padding-top: var(--正文上边距) !important;
  padding-right: var(--正文右边距) !important;
  padding-left: var(--正文左边距) !important;
  padding-bottom: var(--正文下边距) !important;
}


/* --- 头像区域 --- */

.mesAvatarWrapper {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  pointer-events: none;
  margin: 0 !important;
  z-index: 1 !important;
}

.mesAvatarWrapper .avatar {
  position: absolute !important;
  top: var(--头像上下) !important;
  left: var(--头像左右) !important;
  transform: translateX(-50%) !important;
  width: var(--头像宽度) !important;
  height: var(--头像高度) !important;
  overflow: visible !important;
  pointer-events: auto;
  margin: 0 !important;
  background: transparent !important;
  z-index: 2 !important;
  transition: filter 0.6s ease;
}

.mesAvatarWrapper .avatar:hover {
  filter: contrast(1.1) brightness(1.05);
}

/* 头像遮罩@栗子 */
.mesAvatarWrapper .avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  object-position: var(--头像遮罩位置) !important;
  box-shadow:
    0 0 0 2px rgba(90, 100, 105, 0.3),
    0 0 0 3px rgba(255, 255, 255, 0.5),
    3px 4px 8px rgba(90, 100, 105, 0.35) !important;
  filter: saturate(0.7) contrast(1.05) !important;
  /* saturate(0.6) = 60%饱和度，1=原始，0=全灰 */
  /* ✏️ 头像遮罩图（中间透明异形PNG） */
   mask: url('https://iili.io/CRJwbix.png') center / contain no-repeat;
  -webkit-mask: url('https://iili.io/CRJwbix.png') center / contain no-repeat;
}

/* ✏️ 头像框装饰（伪元素，中间镂空PNG才能露出头像） */
.mesAvatarWrapper .avatar::after {
  content: "" !important;
  position: absolute !important;
  top: 43% !important;
  left: 66% !important;
  transform: translate(-50%, -50%) !important;
  width: 110% !important;
  height: 110% !important;
  background-image: url('https://iili.io/C7Y0xGn.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  pointer-events: none !important;
  z-index: 3 !important;
}

.mesAvatarWrapper .avatar {
    pointer-events: none !important;
}

/* --- 角色名字·纵排竖字版--- */

.mes .ch_name {
  display: contents !important;
}

.name_text {
  position: absolute !important;
  /* ⭐ 纵排竖字核心 */
  writing-mode: vertical-rl !important;
  text-orientation: upright !important;
  /* 位置：从顶部down，靠右 */
  top: 0px !important;
  margin-top: var(--名字上下) !important;
  left: var(--名字左右) !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  color: var(--主文字色) !important;
  font-size: var(--名字字体大小) !important;
  font-weight: normal !important;
  letter-spacing: 0.5px !important;     /* ✏️ 竖排间距，比横排要小 */
  z-index: 10 !important;
  /* 不需要white-space:nowrap，竖排自然换行 */
  /* 墨描边确保可见 */
  -webkit-text-stroke: var(--墨描边宽) var(--墨描边色);
  paint-order: stroke fill;
  filter: var(--烛光投影);
}

/* 名字上方装饰符 ◎（竖排时在字上方） */
.name_text::before {
  content: "◎";
  display: block;
  writing-mode: horizontal-tb !important;  /* 符号横排 */
  font-size: 8px !important;
  color: rgba(38, 42, 48, 0.45);
  text-align: center;
  margin-bottom: 3px;
}


/* --- 时间戳 --- */
.timestamp {
  position: absolute !important;
  top: 0!important;
  margin-top: var(--时间戳上下) !important;
  margin-left: var(--时间戳左右) !important;
  transform: translateX(-50%) !important;
  color: rgba(255, 255, 255, 1) !important;
  font-size: var(--时间戳字体大小) !important;
  letter-spacing: 0.12em !important;
  white-space: nowrap;
  z-index: 10 !important;
  -webkit-text-stroke: var(--墨描边宽) var(--墨描边色);
  paint-order: stroke fill;
  filter: var(--烛光投影);
}


/* --- 三元素·稳定定位写法@毛毛雨--- */
/* 核心：用margin-top百分比控制位置，比px更稳定 */

.mes .mesIDDisplay,
.mes .tokenCounterDisplay,
.mes .mes_timer {
  position: absolute !important;
  top: 0 !important;
  font-size: var(--三元素字体大小) !important;
  color: rgba(38, 42, 48, 0.55) !important;
  font-weight: normal !important;
  opacity: 1 !important;
  z-index: 10 !important;
  white-space: nowrap;
  pointer-events: auto;
  letter-spacing: 0.05em;
  -webkit-text-stroke: var(--墨描边宽) var(--墨描边色);
  paint-order: stroke fill;
  filter: var(--烛光投影);
}

/* ✏️ 三元素横向分布位置，用margin-top控制纵向，用left控制横向 */
.mes .mesIDDisplay {
  margin-top: var(--楼层上下) !important;
  margin-left: var(--楼层左右) !important;
  transform: translateX(-50%) !important;
}

.mes .mes_timer {
  margin-top: var(--计时器上下) !important;
  margin-left: var(--计时器左右) !important;
  transform: translateX(-50%) !important;
}

.mes .tokenCounterDisplay {
  margin-top: var(--计数器上下) !important;
  margin-left: var(--计数器左右) !important;
  transform: translateX(-50%) !important;
}


/* --- 正文文字（两端对齐）@咩野 --- */
.mes .mes_text {
  color: var(--主文字色) !important;
  font-weight: normal !important;
  line-height: 1.8 !important;
  text-align: justify !important;
  text-justify: inter-ideograph !important;
  letter-spacing: 0.01em !important;
  overflow-wrap: anywhere;
  padding: 0 !important;
  margin: 0 !important;
}

.mes_text p {
  text-align: justify !important;
  text-justify: inter-ideograph !important;
  margin: 0 0 1em 0 !important;
}

.mes_text p:last-child {
  margin-bottom: 0 !important;
}

.mes.last_mes .mesAvatarWrapper {
  padding-bottom: 5px !important;
}


.del_checkbox {
  position: absolute !important;
  opacity: 1 !important;
  z-index: 100 !important;
  top: 260px !important;     /* ✏️ 根据气泡文字区域位置调整，与--文本区域上边距对应 */
  left: 20px !important;
}


/* --- 气泡内按钮（小铅笔&省略号）·移到顶部 --- */

.mes_button,
.extraMesButtons > div {
  filter: none !important;
}

.mes_buttons {
  position: absolute !important;
  top:0px !important;
   margin-top: var(--按钮组上下) !important;
  margin-left: var(--按钮组左右) !important;
  display: flex !important;
  gap: var(--按钮间距) !important;
  z-index: 20 !important;
  opacity: 1;
  transition: opacity 0.4s ease;
   -webkit-text-stroke: var(--墨描边宽) var(--墨描边色);
  paint-order: stroke fill;
  filter: var(--烛光投影);
  overflow: visible!important;
}

.mes:hover .mes_buttons {
  opacity: 1;
}

.mes_buttons .mes_button {
  color: rgba(38, 42, 48, 0.5) !important;
  opacity: 1 !important;
    -webkit-text-stroke: var(--墨描边宽) var(--墨描边色);
  paint-order: stroke fill;
  filter: var(--烛光投影);
  transition: transform 0.25s ease, color 0.25s ease;
}

.mes_buttons .mes_button:hover {
  color: var(--主文字色) !important;
  transform: translateY(-2px);
}

.mes_buttons .mes_button:active {
  transform: var(--按钮按下);
}

.extraMesButtons {
  position: absolute !important;
  top:0px !important;
  margin-top:0px !important;
  margin-right: 55px !important;
  gap:2px !important;
  /* 这样菜单会从右边起点向左延伸，不会超出屏幕右侧 */
  z-index: 100 !important;
  overflow: visible!important;
}

/* ===== 按钮图片替换区 ===== */
/* ✏️ 如需替换小铅笔图标为图片 */

.mes_buttons .fa-pencil::before, .mes_buttons .fa-pencil-alt::before { display: none !important; }
.mes_buttons .fa-pencil, .mes_buttons .fa-pencil-alt {
  background: url('https://iili.io/CRXPPgp.png') no-repeat center / contain !important;
  width: 45px !important; height: 45px !important;
  margin-top: -22px !important;
  color: transparent !important; font-size: 0 !important;
}
/* ✏️ 如需替换省略号图标为图片 */

.mes_buttons .fa-ellipsis::before, .mes_buttons .fa-ellipsis-h::before { display: none !important; }
.mes_buttons .fa-ellipsis, .mes_buttons .fa-ellipsis-h {
  background: url('https://iili.io/CRXUnB2.png') no-repeat center / contain !important;
  width: 45px !important; height: 45px !important;
    margin-top: -15px !important;
  color: transparent !important; font-size: 0 !important;
}


/* --- 编辑按钮（正文编辑区）·变量控制位置 --- */
.mes_edit_buttons {
  filter: none !important;
  position: absolute !important;
  margin-top: var(--编辑按钮上下) !important;     /* ✏️ 用变量控制确认/取消按钮位置 */
  margin-right: var(--编辑按钮左右) !important;
  z-index: 25;
}

/* ✏️ 如需替换编辑确认/取消按钮为图片 */
/*
.mes_edit_done::before, .mes_edit_cancel::before { display: none !important; }
.mes_edit_done, .mes_edit_cancel {
  background: url('✏️ 确认/取消图标链接') no-repeat center / contain !important;
  width: 25px !important; height: 25px !important;
  color: transparent !important; font-size: 0 !important;
}
*/


/* --- 文字样式核心区 --- */

/* 斜体：荧光笔效果（65%位置） */
.mes_text em,
.mes_text i {
  color: var(--主文字色) !important;
  font-style: italic !important;
  background: linear-gradient(
    to top,
    transparent 0%,
    transparent 30%,
    var(--斜体背景色) 30%,
    var(--斜体背景色) 65%,
    transparent 65%,
    transparent 100%
  ) !important;
  padding: 0 3px !important;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}

/* 引用：矩形+文字+同色双层边框+阴影+去引号 */
.mes_text q {
  background-color: var(--引用背景色) !important;
  color: var(--引用文字色) !important;
  padding: 3px 4px !important;
  border: 1px solid var(--引用文字色) !important;
  outline: 1px solid var(--引用文字色) !important;
  outline-offset: -3px !important;
  box-shadow: var(--阴影黑色不大) !important;
  font-style: normal !important;
  font-weight: normal !important;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}

/* 去除引用前后引号 */
.mes_text q::before,
.mes_text q::after {
  content: none !important;
}

/* 加粗 */
.mes_text strong,
.mes_text b {
  color: var(--主文字色) !important;
  font-weight: 600 !important;
  letter-spacing: 0.05em;
}

/* 下划线 */
.mes_text u {
  color: rgba(38, 42, 48, 0.75) !important;
  text-decoration: underline;
  text-decoration-color: rgba(38, 42, 48, 0.35);
  text-underline-offset: 3px;
}

/* 引用块 */
.mes_text blockquote {
  border: 1px solid rgba(90, 100, 105, 0.2) !important;
  border-left: 3px double var(--主文字色) !important;
  background: rgba(90, 100, 105, 0.05) !important;
  color: rgba(38, 42, 48, 0.88) !important;
  padding: 10px 16px !important;
  margin: 14px 0 !important;
  font-style: italic;
  box-shadow: var(--阴影黑色不大) !important;
}

/* 单行代码 */
.mes_text :not(pre) > code {
  background-color: rgba(90, 100, 105, 0.08) !important;
  border: 1px solid rgba(90, 100, 105, 0.2) !important;
  color: var(--主文字色) !important;
  padding: 1px 6px !important;
  font-family: var(--主字体), monospace;
  box-shadow: var(--阴影黑色不大) !important;
}

/* 代码块 */
.mes_text pre {
  background-color: rgba(255, 255, 255, 0.6) !important;
  border: 1px solid rgba(90, 100, 105, 0.2) !important;
  padding: 12px !important;
  overflow-x: auto;
  box-shadow: var(--阴影内凹深) !important;
}

.mes_text pre code {
  background: transparent !important;
  border: none !important;
  color: var(--主文字色) !important;
  padding: 0 !important;
  box-shadow: none !important;
}

/* 分割线@hy */
hr {
  background-image: url("https://iili.io/CRhvmbf.png") !important;
  background-repeat: no-repeat !important;
  background-position: center center !important;
  background-size: contain !important;
  background-color: transparent !important;
  margin: 10px auto !important;
  height: 95px !important;          /* ✏️ 分割线图片显示高度 */
  width: 100% !important;      
  min-height: 1px !important;
  border: 0 !important;
  opacity: 1 !important;
  box-shadow: none !important;
  box-sizing: border-box !important;
}

/* 文字选中@时鸢 */
::selection {
  background-color: rgba(90, 120, 130, 0.25);
  color: var(--主文字色);
  text-shadow: none;
}

::-moz-selection {
  background-color: rgba(90, 120, 130, 0.25);
  color: var(--主文字色);
  text-shadow: none;
}

input::selection,
textarea::selection {
  background-color: rgba(90, 120, 130, 0.25);
  color: var(--主文字色);
}


/* --- 翻页按钮 --- */
.swipe_left,
.swipe_right {
  color: rgba(38, 42, 48, 0.4) !important;
  font-size: 14px !important;
  transition: transform 0.4s ease, color 0.3s ease;
}

.swipe_left {
  position: absolute !important;
  bottom:0px !important;
  margin-bottom: var(--左箭头上下) !important;
  margin-left: var(--左箭头左右) !important;
}

.swipe_right {
  position: absolute !important;
  bottom:0px !important;
  margin-bottom: var(--右箭头上下) !important;
  margin-right: var(--右箭头左右) !important;
}

.swipe_left:hover,
.swipe_right:hover {
  color: var(--主文字色) !important;
  transform: translateY(-2px);
}

/* 翻页按钮图片替换区 */
/* ✏️ 如需替换左箭头为图片 */

.fa-chevron-left::before { content: "" !important; display: none !important; }
.fa-chevron-left {
  display: inline-block !important;
  width: 45px !important; height: 45px !important;
  background-image: url('https://iili.io/CRXUnB2.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  opacity: 1 !important;
}
.fa-chevron-right::before { content: "" !important; display: none !important; }
.fa-chevron-right {
  display: inline-block !important;
  width: 45px !important; height: 45px !important;
  background-image: url('https://iili.io/CRXPPgp.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  opacity: 1 !important;
}


/* --- 页码·变量控制位置 --- */
.swipes-counter {
  position: absolute !important;
  bottom:0px !important;
  margin-bottom: var(--页码上下) !important;      /* ✏️ 用变量控制页码位置 */
  margin-right: var(--页码左右) !important;
  transform: translateX(-50%) !important;
  color: rgba(15, 15, 15, 0.8) !important;
  font-size: var(--页码大小) !important;
  letter-spacing: 0.1em;
  z-index: 50 !important;
  -webkit-text-stroke: var(--墨描边宽) var(--墨描边色);
  paint-order: stroke fill;
  filter: var(--烛光投影);
  opacity: 1 !important;
}

/* === 小幽灵 === */
.mes_ghost.fa-ghost[title][data-i18n] {
  position: absolute !important;
  margin-left: 4px !important;
  width: var(--小幽灵宽度) !important;
  height: var(--小幽灵高度) !important;
  transform: translate(var(--小幽灵左右), var(--小幽灵上下)) !important;
  color: transparent !important;
  /* ✏️ 替换成你的图片链接 */
  background-image: url("https://iili.io/CYaOeUX.png");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  /* 左边渐隐遮罩（可选） */
  -webkit-mask-image: linear-gradient(to right,
    transparent 0,
    #fff var(--小幽灵左渐隐),
    #fff 100%) !important;
  mask-image: linear-gradient(to right,
    transparent 0,
    #fff var(--小幽灵左渐隐),
    #fff 100%) !important;
  -webkit-mask-size: 100% 100%;
  mask-size: 100% 100%;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  z-index: 3 !important;
}

/* ===== 五、滚动条+滑动条@墨千尾 ===== */

/* --- 滑动条本体 --- */
input[type="range"] {
  -webkit-appearance: none !important;
  appearance: none !important;
  width: 100% !important;
  background: transparent !important;
  cursor: pointer !important;
  filter: none !important;
  box-shadow: none !important;
  overflow: visible !important;
}

/* --- 滑轨（你拖动的那条线） --- */
input[type="range"]::-webkit-slider-runnable-track {
  width: 100% !important;
  height: 3px !important;                        /* ✏️ 轨道粗细 */
  background: rgba(90, 100, 105, 0.25) !important; /* ✏️ 轨道颜色 */
  border: none !important;
  cursor: pointer !important;
}

/* --- 滑块（你拖的那个小圆点/图标） --- */
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none !important;
  /* ✏️ 如需替换为图片滑块 */
  background: url('https://iili.io/C78U1YF.png') center / contain no-repeat !important;
  border: none !important;
  box-shadow: none !important;
  width: 60px !important; height: 60px !important;
  margin-top: -28px !important;
}

input[type="range"]:hover::-webkit-slider-thumb,
input[type="range"]:active::-webkit-slider-thumb {
  transform: scale(1.2);
}

/* Firefox兼容 */
input[type="range"]::-moz-range-track {
  height: 3px !important;
  background: rgba(90, 100, 105, 0.25) !important;
  border: none !important;
  cursor: pointer !important;
}

input[type="range"]::-moz-range-thumb {
  border: none !important;
  width: 14px !important;
  height: 14px !important;
  background: var(--主文字色) !important;
  border: 1.5px solid rgba(255, 255, 255, 0.6) !important;
  cursor: pointer !important;
}

/* --- 酒馆滑轨容器（neo-range-slider）--- */
/* 去除左右滑块阴影@玲 */
.neo-range-slider {
  height: 3px !important;                        /* ✏️ 和滑轨高度保持一致 */
  background: rgba(90, 100, 105, 0.2) !important; /* ✏️ 容器底色 */
  border: none !important;
  box-shadow: none !important;
  margin-bottom: 0px !important;
  cursor: pointer !important;
}

.neo-range-slider,
#temp_openai,
#freq_pen_openai,
#pres_pen_openai,
#top_p_openai,
#top_k_openai,
#openai_max_context {
  filter: none !important;
}

/* --- 滑块下面的数值输入框 --- */
input:not([type="file"]):not([type="image"]):not([type="checkbox"]):not([type="radio"]):not([type="range"]) {
  background: linear-gradient(
    to right,
