  border: 1px solid rgba(90, 100, 105, 0.15) !important;
  padding: 3px 8px;
  box-shadow: var(--阴影黑色不大) !important;
  letter-spacing: 0.08em;
  -webkit-text-stroke: var(--墨描边宽) var(--墨描边色);
  paint-order: stroke fill;
  filter: var(--烛光投影);
}

/* ===== 角色卡列表条目 ===== */
.avatar-container,
.bogus_folder_select,
.character_select {
  background: rgba(255, 255, 255, 0.5) !important;
  border: 1px solid rgba(90, 100, 105, 0.15) !important;
  color: var(--主文字色) !important;
  box-shadow: var(--阴影多层奢华) !important;
  padding: 6px;
  margin-top: 8px;
  transition: all 0.35s ease;
}

.avatar-container:hover,
.character_select:hover {
  background: rgba(255, 255, 255, 0.7) !important;
  transform: translateY(-2px);
}


/* =================================================
   ✨ 角色详情大头像布局与装饰框写法@毛毛雨
   ================================================= */

#avatar_div {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 25px !important;
  padding: 25px 15px !important;
  position: relative;
}

/* 头像容器：成为定位锚点 */
#avatar_div .avatar {
  position: relative !important;
  width: auto !important;
  height: auto !important;
  background: none !important;
  display: inline-block !important;
  transition: transform 0.5s ease;
}

#avatar_div .avatar:hover {
  transform: translateY(-3px);
}

/* 大头像图片本身 */
#avatar_div .avatar img {
  left:-20px;
  margin-bottom:-45px !important;
  width: 300px !important;          /* ✏️ 头像宽度 */
  height: 280px!important;
  aspect-ratio: 1.65 / 1 !important;  /* ✏️ 头像比例 */
  object-fit: cover !important;
  display: block !important;
  border: 1.5px solid rgba(90, 100, 105, 0.4) !important;
  box-shadow:
    0 0 0 2px rgba(255, 255, 255, 0.5),
    0 0 0 3px rgba(90, 100, 105, 0.25),
    5px 6px 12px rgba(90, 100, 105, 0.3) !important;
  filter: saturate(0.7) contrast(1.05) !important;
  /* saturate(0.6) = 60%饱和度，1=原始，0=全灰 */
  position: relative;
  z-index: 1;
  object-position:  var(--头像遮罩位置);
   mask: url('https://iili.io/CRJwbix.png') center / contain no-repeat;
  -webkit-mask: url('https://iili.io/CRJwbix.png') center / contain no-repeat;
}

/* ⭐ 大头像装饰框 */
#avatar_div .avatar::after {
  content: '' !important;
  position: absolute !important;
  top: -55px !important;           /* ✏️ 向上溢出多少（数值越大越往上） */
  left: 56.5% !important;
  transform: translateX(-50%) !important;
  width: 360px !important;          /* ✏️ 框宽度（建议比头像宽80-100px） */
  height: 350px !important;         /* ✏️ 框高度（建议比头像高150-200px） */
  /* ✏️ 装饰框图片（必须中间镂空透明PNG，才能露出头像！） */
   background: url('https://iili.io/C7Y0xGn.png') no-repeat center / contain !important;
  pointer-events: none !important;
  z-index: 2 !important;
  transition: transform 0.5s ease;
}

#avatar_div .avatar:hover::after {
  transform: translateX(-50%) translateY(-2px);
}

/* 角色控件区（按钮组居中） */
#avatar_controls {
  display: flex !important;
  flex-wrap: wrap !important;
  justify-content: center !important;
  align-items: center !important;
  gap: 8px !important;
  width: 100% !important;
  padding: 10px 0 !important;
}

#avatar_controls > div:first-child {
  display: flex !important;
  flex-wrap: wrap !important;
  justify-content: center !important;
  gap: 8px !important;
}

#avatar_controls button,
#avatar_controls .menu_button {
  padding: 6px 14px !important;
  font-size: 11px !important;
  letter-spacing: 0.08em !important;
}


/* ===== Tag ===== */
.tag {
  color: var(--主文字色);
  background-color: rgba(255, 255, 255, 0.4) !important;
  padding: 0.15rem 0.4rem;
  border: 1px solid rgba(90, 100, 105, 0.2);
  box-shadow: var(--阴影黑色不大);
  letter-spacing: 0.04em;
}

.welcomePanel {
  background: transparent !important;
}
.welcomeRecent,
.welcomeHeader,
.welcomeHeaderTitle {
  background: rgba(255, 255, 255, 0.5)   !important;
  border: none !important;
  box-shadow: var(--阴影多层奢华) !important;
  color: var(--主文字色) !important;
}
.welcomeRecent:hover {
  box-shadow: var(--阴影面板) !important;
}
.welcomeRecent .avatar img {
  border: none !important;
  box-shadow: var(--阴影多层奢华) !important;
}

/* 欢迎界面整体允许溢出 + 给按钮组留空间 */
.welcomeRecent {
  overflow: visible !important;
  position: relative !important;
}

/* 欢迎界面内容区域允许溢出 */
.welcomeRecent .flex-container,
.welcomeRecent .flex-container.alignItemsCenter {
  overflow: visible !important;
  flex-wrap: wrap !important;
}

/* 按钮组往左缩一点 */
.chatActions {
  padding-right: 5px !important;  /* ✏️ 调大这个数字 */
  overflow: visible !important;
}

/* 欢迎界面整体下移 */
.welcomePanel {
  padding-top: 30px !important;
}

/* =================================================
   ✨ User快速切换插件
   ================================================= */

/* 隐藏下拉箭头 */
#quickPersonaCaret {
  display: none !important;
}

form.world_entry_form.wi-card-entry {
  background: transparent !important;
  background-attachment: fixed !important;
  border: none !important;
  box-shadow: none !important;
}

/* =================================================
   ✨ 文字描边系统

   ================================================= */

/* 正文不描边（保护阅读舒适性），只给加粗轻加一点 */
.mes_text strong,
.mes_text b {
  -webkit-text-stroke: 0.5px var(--墨描边色);
  paint-order: stroke fill;
  filter: drop-shadow(0 0 1.5px rgba(140, 150, 165, 0.2));
}


/* =================================================
   ✨ 精致动效：烛光呼吸浮动
   ================================================= */

@keyframes gentleFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-1.5px); }
}

/* 展开箭头（向下）替换 */
.fa-circle-chevron-down,
.inline-drawer-icon.fa-circle-chevron-down {
  display: inline-block !important;
  filter: none !important;
  background-image: url("https://iili.io/CaRTKFV.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  width: 30px !important;
  height: 30px !important;
}
